'use strict';
(() => {
 const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
 const products=window.SHOP_DATA.products;
 const format=n=>new Intl.NumberFormat('ru-RU').format(n)+' ₽';
 const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 let saved=new Set();try{saved=new Set(JSON.parse(localStorage.getItem('ishmot-favorites')||'[]'))}catch{}
 let activeItem=null,photoIndex=0,previousFocus=null,toastTimer;
 function notify(message){$('.toast').textContent=message;$('.toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('.toast').classList.remove('show'),2200)}
 function productCard(p){return `<article class="product-card" data-card="${esc(p.id)}"><button class="product-image" data-product="${esc(p.id)}" aria-label="Подробнее: ${esc(p.title)}"><img src="${esc(p.images[0]||'assets/photo-unavailable.svg')}" alt="${esc(p.title)}" loading="lazy" width="540" height="540">${p.images[1]?`<img class="hover-image" src="${esc(p.images[1])}" alt="" loading="lazy" width="540" height="540">`:''}${p.oldPrice>p.price?`<span class="product-tag">−${Math.round((1-p.price/p.oldPrice)*100)}%</span>`:''}<span class="view-product" aria-hidden="true">Рассмотреть</span></button><button class="save-button saved" data-save="${esc(p.id)}" aria-label="Удалить из избранного" aria-pressed="true">♥</button><div class="product-meta"><span>${esc(p.category.toUpperCase())}</span><span>${p.images.length} ФОТО</span></div><button class="product-title" data-product="${esc(p.id)}">${esc(p.title)}</button><div class="product-price"><strong>${format(p.price)}</strong>${p.oldPrice>p.price?`<del>${format(p.oldPrice)}</del>`:''}</div><button class="product-details f7-button" data-product="${esc(p.id)}"><img class="ui-icon" src="assets/icons/images-outline.svg" alt="" aria-hidden="true">Фото и описание</button></article>`}
 function render(){const list=products.filter(p=>saved.has(p.id));$('#favorites-grid').innerHTML=list.map(productCard).join('');$('#favorites-grid').hidden=!list.length;$('#favorites-empty').hidden=!!list.length;$('#favorites-count').textContent=`${list.length} ${list.length===1?'товар':list.length>=2&&list.length<=4?'товара':'товаров'}`;$$('.nav-saved-count').forEach(b=>{b.textContent=list.length;b.setAttribute('aria-label',`${list.length} сохранённых товаров`)})}
 function save(id){if(saved.has(id)){saved.delete(id);notify('Убрали из избранного')}else{saved.add(id);notify('Добавили в избранное')}try{localStorage.setItem('ishmot-favorites',JSON.stringify([...saved]))}catch{}render();if(activeItem){const on=saved.has(activeItem.id);$('#modal-save').textContent=on?'♥':'♡';$('#modal-save').setAttribute('aria-pressed',String(on));$('#modal-save').setAttribute('aria-label',on?'Удалить из избранного':'Добавить в избранное')}}
 function cleanDescription(text){return String(text||'').replace(/Показать\s*ещ[её]/gi,'').replace(/[\p{Extended_Pictographic}\uFE0E\uFE0F\u200D]/gu,'').replace(/[\u2190-\u21ff✓✔☑]/g,'').split(/\r?\n/).map(s=>s.replace(/^[\s*•●▪▫►▸\-–—]+/,'').replace(/([а-яё])([A-Za-z])/g,'$1 $2').replace(/[ \t\u00a0]+/g,' ').trim()).filter(Boolean)}
 function formatDescriptionLines(lines){let html='',specs=[],list=[];const flushSpecs=()=>{if(specs.length){html+='<dl>'+specs.map(([k,v])=>`<div class="spec-row"><dt>${esc(k)}</dt><dd>${esc(v)}</dd></div>`).join('')+'</dl>';specs=[]}};const flushList=()=>{if(list.length){html+='<ul>'+list.map(s=>`<li>${esc(s)}</li>`).join('')+'</ul>';list=[]}};for(const line of lines){if(/^(Характеристики|Преимущества|Виды оплаты|В услугу входит|Комплектация|Описание|Стоимость|Условия)[\s:]*$/i.test(line)){flushSpecs();flushList();html+=`<h3>${esc(line.replace(/:$/,''))}</h3>`;continue}const match=line.match(/^([^:—]{2,48})\s*(?:[:]| — )\s*(.+)$/);if(match&&!/^https?/i.test(line)&&!/^(Цена|При оплате|Если|Полностью)/i.test(line)){flushList();specs.push([match[1],match[2]]);continue}flushSpecs();if(line.length<130)list.push(line);else{flushList();html+=`<p>${esc(line)}</p>`}}flushSpecs();flushList();return html}
 function renderDescription(item){const main=[],terms=[];let inTerms=false;for(const line of cleanDescription(item.description)){if(/^(Виды оплаты|Цена за товар|При оплате|Товар представленный|Товар, представленный)/i.test(line))inTerms=true;if(inTerms||/рассрочк|кредит без|наличный расч[её]т/i.test(line)){terms.push(line);continue}main.push(line)}let result='<h3>О товаре</h3>'+formatDescriptionLines(main);if(['14651329','14651302'].includes(item.id))result+='<p class="source-conflict">В карточке магазина есть расхождения в характеристиках. Перед покупкой уточните точную комплектацию у продавца.</p>';if(terms.length)result+='<details><summary>Оплата, получение и условия</summary>'+formatDescriptionLines(terms)+'</details>';return result}
 function updatePhoto(){const imgs=activeItem.images.length?activeItem.images:['assets/photo-unavailable.svg'];photoIndex=(photoIndex+imgs.length)%imgs.length;$('#modal-image').src=imgs[photoIndex];$('#modal-image').alt=activeItem.title+' — фото '+(photoIndex+1);$('#photo-count').textContent=`${photoIndex+1} / ${imgs.length}`;$('#photo-prev').hidden=$('#photo-next').hidden=imgs.length<2;$('#modal-thumbs').innerHTML=imgs.map((src,i)=>`<button class="${i===photoIndex?'active':''}" data-photo="${i}" aria-label="Фотография ${i+1}" aria-pressed="${i===photoIndex}"><img src="${esc(src)}" alt="" loading="lazy"></button>`).join('')}
 function openItem(item){if(!item)return;activeItem=item;photoIndex=0;previousFocus=document.activeElement;$('#modal-title').textContent=item.title;$('#modal-category').textContent=item.category.toUpperCase()+' / АЙШМОТ';$('#modal-price').textContent=format(item.price);$('#modal-old-price').textContent=item.oldPrice>item.price?format(item.oldPrice):'';$('#modal-availability').textContent='Наличие и условия оплаты уточняйте у консультанта.';$('#modal-description').innerHTML=renderDescription(item);$('#modal-vk').href=item.source;$('#modal-vk').textContent='Открыть в ВК';const on=saved.has(item.id);$('#modal-save').textContent=on?'♥':'♡';$('#modal-save').setAttribute('aria-pressed',String(on));$('#modal-save').setAttribute('aria-label',on?'Удалить из избранного':'Добавить в избранное');updatePhoto();const dialog=$('#product-dialog');if(typeof dialog.showModal==='function'){if(!dialog.open)dialog.showModal()}else{dialog.setAttribute('open','');dialog.classList.add('dialog-fallback')}dialog.scrollTop=0;document.body.classList.add('modal-open');$('.modal-close').focus()}
 function closeModal(){const dialog=$('#product-dialog');if(typeof dialog.close==='function')dialog.close();else{dialog.removeAttribute('open');dialog.classList.remove('dialog-fallback');dialog.dispatchEvent(new Event('close'))}}
 $('#favorites-grid').addEventListener('click',e=>{const heart=e.target.closest('[data-save]');if(heart){save(heart.dataset.save);return}const item=e.target.closest('[data-product],[data-card]');if(item)openItem(products.find(p=>p.id===(item.dataset.product||item.dataset.card)))});
 $('#modal-save').addEventListener('click',()=>save(activeItem.id));$('.modal-close').addEventListener('click',closeModal);
 $('#product-dialog').addEventListener('close',()=>{document.body.classList.remove('modal-open');(previousFocus?.isConnected?previousFocus:$('.nav-favorites')).focus({preventScroll:true})});
 $('#product-dialog').addEventListener('click',e=>{if(e.target===$('#product-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal()}});
 $('#photo-prev').addEventListener('click',()=>{photoIndex--;updatePhoto()});$('#photo-next').addEventListener('click',()=>{photoIndex++;updatePhoto()});
 $('#modal-thumbs').addEventListener('click',e=>{const b=e.target.closest('[data-photo]');if(b){photoIndex=+b.dataset.photo;updatePhoto()}});
 let touchStart=0;$('#modal-image').addEventListener('touchstart',e=>{touchStart=e.changedTouches[0].screenX},{passive:true});$('#modal-image').addEventListener('touchend',e=>{const dx=e.changedTouches[0].screenX-touchStart;if(Math.abs(dx)>50){photoIndex+=dx<0?1:-1;updatePhoto()}},{passive:true});
 document.addEventListener('keydown',e=>{if($('#product-dialog').open){if(e.key==='Escape'){e.preventDefault();closeModal()}if(e.key==='ArrowRight'){photoIndex++;updatePhoto()}if(e.key==='ArrowLeft'){photoIndex--;updatePhoto()}}});
 $('.menu-toggle').addEventListener('click',()=>{const open=$('.header').classList.toggle('menu-open');$('.menu-toggle').setAttribute('aria-expanded',String(open));$('.menu-toggle').setAttribute('aria-label',open?'Закрыть меню':'Открыть меню')});$$('.header nav a').forEach(a=>a.addEventListener('click',()=>{$('.header').classList.remove('menu-open');$('.menu-toggle').setAttribute('aria-expanded','false');$('.menu-toggle').setAttribute('aria-label','Открыть меню')}));
 document.addEventListener('error',e=>{if(e.target.tagName==='IMG'&&!e.target.src.endsWith('photo-unavailable.svg'))e.target.src='assets/photo-unavailable.svg'},true);
 window.addEventListener('storage',e=>{if(e.key==='ishmot-favorites'){try{saved=new Set(JSON.parse(e.newValue||'[]'))}catch{saved=new Set()}render()}});
 render();
})();
